/* CSS PART 1 OF 4 */

/* =========================================
   JOSH BROOKS CONSTRUCTION & RENOVATION
   Design foundation: Modern Front Range craft
   ========================================= */

/* 1. DESIGN TOKENS */

:root {
  color-scheme: light;

  --color-ink: #202b32;
  --color-ink-soft: #43515a;
  --color-muted: #69777d;
  --color-paper: #f7f6f2;
  --color-white: #ffffff;
  --color-surface: #eeede7;
  --color-border: #deded6;

  --color-primary: #263d4a;
  --color-primary-dark: #192d38;
  --color-accent: #c47743;
  --color-accent-dark: #a85e32;
  --color-accent-light: #e8c6a9;

  --font-heading: "Montserrat", "Arial", sans-serif;
  --font-body: "Inter", "Segoe UI", sans-serif;

  --font-size-xs: 0.75rem;
  --font-size-sm: 0.875rem;
  --font-size-base: 1rem;
  --font-size-lg: 1.125rem;
  --font-size-xl: 1.375rem;
  --font-size-2xl: clamp(1.75rem, 3vw, 2.5rem);
  --font-size-3xl: clamp(2.25rem, 4.5vw, 3.75rem);
  --font-size-hero: clamp(2.75rem, 6.5vw, 5.75rem);

  --line-height-tight: 1.08;
  --line-height-heading: 1.2;
  --line-height-body: 1.7;

  --weight-regular: 400;
  --weight-medium: 500;
  --weight-semibold: 600;
  --weight-bold: 700;
  --weight-heavy: 800;

  --space-1: 0.375rem;
  --space-2: 0.75rem;
  --space-3: 1rem;
  --space-4: 1.5rem;
  --space-5: 2rem;
  --space-6: 3rem;
  --space-7: 4rem;
  --space-8: 5rem;
  --space-9: 7rem;

  --container-width: 1200px;
  --container-wide: 1440px;
  --container-narrow: 780px;

  --header-height: 84px;

  --radius-sm: 4px;
  --radius-md: 10px;
  --radius-lg: 18px;

  --shadow-soft: 0 8px 30px rgba(32, 43, 50, 0.07);
  --shadow-medium: 0 18px 50px rgba(32, 43, 50, 0.12);

  --transition-fast: 180ms ease;
  --transition-normal: 300ms ease;
}


/* 2. RESET AND GLOBAL FOUNDATIONS */

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  scroll-padding-top: calc(var(--header-height) + 20px);
  -webkit-text-size-adjust: 100%;
}

body {
  margin: 0;
  min-width: 320px;
  background: var(--color-paper);
  color: var(--color-ink);
  font-family: var(--font-body);
  font-size: var(--font-size-base);
  font-weight: var(--weight-regular);
  line-height: var(--line-height-body);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body,
button,
input,
select,
textarea {
  font-family: var(--font-body);
}

img,
picture,
video,
svg {
  display: block;
  max-width: 100%;
}

img {
  height: auto;
}

button,
input,
select,
textarea {
  font: inherit;
}

button {
  cursor: pointer;
}

a {
  color: inherit;
  text-decoration: none;
}

ul,
ol {
  padding-left: 1.4rem;
}

p,
h1,
h2,
h3,
h4,
h5,
h6 {
  margin-top: 0;
}

p {
  margin-bottom: 1.25rem;
}

::selection {
  background: var(--color-accent);
  color: var(--color-white);
}

:focus {
  outline: none;
}

:focus-visible {
  outline: 3px solid var(--color-accent);
  outline-offset: 4px;
  border-radius: var(--radius-sm);
}

[hidden] {
  display: none !important;
}


/* 3. TYPOGRAPHY */

h1,
h2,
h3,
h4,
h5,
h6 {
  color: var(--color-ink);
  font-family: var(--font-heading);
  font-weight: var(--weight-bold);
  letter-spacing: -0.035em;
  line-height: var(--line-height-heading);
}

h1 {
  font-size: var(--font-size-hero);
  font-weight: var(--weight-heavy);
  line-height: var(--line-height-tight);
}

h2 {
  font-size: var(--font-size-3xl);
  line-height: 1.12;
}

h3 {
  font-size: var(--font-size-2xl);
}

h4 {
  font-size: var(--font-size-xl);
}

small,
.text-small {
  font-size: var(--font-size-sm);
}

.text-muted {
  color: var(--color-muted);
}

.text-light {
  color: var(--color-white);
}

.text-accent {
  color: var(--color-accent);
}

.eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 0.65rem;
  margin-bottom: 1.15rem;
  color: var(--color-accent-dark);
  font-family: var(--font-heading);
  font-size: var(--font-size-xs);
  font-weight: var(--weight-bold);
  letter-spacing: 0.16em;
  line-height: 1.5;
  text-transform: uppercase;
}

.eyebrow::before {
  width: 28px;
  height: 2px;
  background: currentColor;
  content: "";
}

.section-heading {
  max-width: 760px;
  margin-bottom: 1.25rem;
}

.section-intro {
  max-width: 660px;
  color: var(--color-muted);
  font-size: var(--font-size-lg);
  line-height: 1.75;
}


/* 4. PAGE GRID AND CONTAINERS */

.site-shell {
  width: 100%;
  overflow: clip;
}

.container {
  width: min(
    var(--container-width),
    calc(100% - 48px)
  );
  margin-inline: auto;
}

.container-wide {
  width: min(
    var(--container-wide),
    calc(100% - 48px)
  );
  margin-inline: auto;
}

.container-narrow {
  width: min(
    var(--container-narrow),
    calc(100% - 48px)
  );
  margin-inline: auto;
}

.section {
  position: relative;
  padding-block: var(--space-9);
}

.section-compact {
  padding-block: var(--space-7);
}

.section-light {
  background: var(--color-paper);
}

.section-white {
  background: var(--color-white);
}

.section-dark {
  background: var(--color-primary);
  color: var(--color-white);
}

.section-dark h2,
.section-dark h3,
.section-dark h4 {
  color: var(--color-white);
}

.section-dark .section-intro {
  color: rgba(255, 255, 255, 0.75);
}


/* 5. SHARED LAYOUT UTILITIES */

.stack {
  display: flex;
  flex-direction: column;
  gap: var(--space-4);
}

.stack-tight {
  display: flex;
  flex-direction: column;
  gap: var(--space-2);
}

.stack-large {
  display: flex;
  flex-direction: column;
  gap: var(--space-6);
}

.cluster {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--space-3);
}

.split {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-5);
}

.grid {
  display: grid;
  gap: var(--space-5);
}

.grid-two {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.grid-three {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.grid-four {
  grid-template-columns: repeat(4, minmax(0, 1fr));
}

.content-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.05fr) minmax(0, 0.95fr);
  align-items: center;
  gap: clamp(2rem, 5vw, 5rem);
}

.centered {
  margin-inline: auto;
  text-align: center;
}

.max-readable {
  max-width: 680px;
}

.full-width {
  width: 100%;
}


/* 6. IMAGE FOUNDATIONS */

.image-frame {
  position: relative;
  overflow: hidden;
  background: var(--color-surface);
  border-radius: var(--radius-md);
}

.image-frame img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.image-cover {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.image-landscape {
  aspect-ratio: 16 / 10;
}

.image-portrait {
  aspect-ratio: 4 / 5;
}

.image-square {
  aspect-ratio: 1;
}


/* 7. ACCESSIBILITY AND MOTION */

.skip-link {
  position: absolute;
  z-index: 9999;
  top: 12px;
  left: 12px;
  padding: 12px 18px;
  transform: translateY(-160%);
  background: var(--color-white);
  color: var(--color-primary-dark);
  border: 2px solid var(--color-accent);
  border-radius: var(--radius-sm);
  font-weight: var(--weight-bold);
}

.skip-link:focus {
  transform: translateY(0);
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    scroll-behavior: auto !important;
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}


/* 8. RESPONSIVE GRID FOUNDATIONS */

@media (max-width: 900px) {
  :root {
    --header-height: 72px;
  }

  .section {
    padding-block: var(--space-8);
  }

  .grid-four {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .content-grid {
    gap: var(--space-5);
  }
}

@media (max-width: 640px) {
  :root {
    --space-7: 3rem;
    --space-8: 3.75rem;
    --space-9: 4.5rem;
  }

  .container,
  .container-wide,
  .container-narrow {
    width: calc(100% - 36px);
  }

  .section {
    padding-block: var(--space-8);
  }

  .grid-two,
  .grid-three,
  .grid-four,
  .content-grid {
    grid-template-columns: minmax(0, 1fr);
  }

  .split {
    align-items: flex-start;
    flex-direction: column;
    gap: var(--space-3);
  }

  .section-heading {
    margin-bottom: 1rem;
  }

  .section-intro {
    font-size: var(--font-size-base);
  }

  .image-landscape {
    aspect-ratio: 5 / 4;
  }
}
