/* CSS PART 2 OF 4 */

/* =========================================
   HEADER, NAVIGATION, HERO & PRIMARY ACTION
   ========================================= */

/* 1. SITE HEADER */

.site-header {
  position: sticky;
  z-index: 1000;
  top: 0;
  width: 100%;
  min-height: var(--header-height);
  background: rgba(255, 255, 255, 0.97);
  border-bottom: 1px solid var(--color-border);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
}

.header-inner {
  display: flex;
  width: min(
    var(--container-wide),
    calc(100% - 48px)
  );
  min-height: var(--header-height);
  margin-inline: auto;
  align-items: center;
  justify-content: space-between;
  gap: 1.5rem;
}

.brand {
  display: inline-flex;
  flex: 0 0 auto;
  align-items: center;
  gap: 0.85rem;
  color: var(--color-primary);
}

.brand-logo {
  display: block;
  width: auto;
  max-width: 190px;
  max-height: 57px;
  object-fit: contain;
}

.brand-name {
  display: flex;
  flex-direction: column;
  gap: 0.1rem;
  font-family: var(--font-heading);
  font-size: 0.98rem;
  font-weight: var(--weight-bold);
  line-height: 1.15;
  letter-spacing: -0.025em;
}

.brand-subtitle {
  color: var(--color-muted);
  font-family: var(--font-body);
  font-size: 0.62rem;
  font-weight: var(--weight-semibold);
  letter-spacing: 0.12em;
  text-transform: uppercase;
}


/* 2. DESKTOP NAVIGATION */

.primary-navigation {
  display: flex;
  align-items: center;
  gap: clamp(0.85rem, 1.6vw, 1.5rem);
}

.primary-navigation ul {
  display: flex;
  align-items: center;
  gap: clamp(0.75rem, 1.5vw, 1.4rem);
  padding: 0;
  margin: 0;
  list-style: none;
}

.primary-navigation a {
  position: relative;
  display: inline-flex;
  min-height: 44px;
  align-items: center;
  color: var(--color-ink-soft);
  font-size: 0.82rem;
  font-weight: var(--weight-semibold);
  transition: color var(--transition-fast);
}

.primary-navigation a::after {
  position: absolute;
  right: 0;
  bottom: 7px;
  left: 0;
  height: 2px;
  transform: scaleX(0);
  transform-origin: left;
  background: var(--color-accent);
  content: "";
  transition: transform var(--transition-normal);
}

.primary-navigation a:hover,
.primary-navigation a[aria-current="page"] {
  color: var(--color-accent-dark);
}

.primary-navigation a:hover::after,
.primary-navigation a[aria-current="page"]::after {
  transform: scaleX(1);
}


/* 3. HEADER CONTACT ACTIONS */

.header-actions {
  display: flex;
  flex: 0 0 auto;
  align-items: center;
  gap: 1rem;
}

.header-phone {
  display: flex;
  flex-direction: column;
  gap: 0.1rem;
  color: var(--color-primary);
  font-size: 0.8rem;
  font-weight: var(--weight-bold);
  line-height: 1.35;
}

.header-phone small {
  color: var(--color-muted);
  font-size: 0.62rem;
  font-weight: var(--weight-semibold);
  letter-spacing: 0.09em;
  text-transform: uppercase;
}


/* 4. SHARED BUTTON SYSTEM */

.button {
  display: inline-flex;
  position: relative;
  min-height: 52px;
  padding: 0.85rem 1.55rem;
  align-items: center;
  justify-content: center;
  gap: 0.65rem;
  border: 1px solid transparent;
  border-radius: var(--radius-sm);
  font-family: var(--font-heading);
  font-size: 0.83rem;
  font-weight: var(--weight-bold);
  line-height: 1.2;
  text-align: center;
  cursor: pointer;
  transition:
    background var(--transition-fast),
    color var(--transition-fast),
    border-color var(--transition-fast),
    transform var(--transition-fast),
    box-shadow var(--transition-fast);
}

.button:hover {
  transform: translateY(-2px);
}

.button:active {
  transform: translateY(0);
}

.button-primary {
  background: var(--color-accent);
  color: var(--color-white);
  border-color: var(--color-accent);
  box-shadow: 0 5px 16px rgba(196, 119, 67, 0.17);
}

.button-primary:hover {
  background: var(--color-accent-dark);
  border-color: var(--color-accent-dark);
  box-shadow: 0 8px 22px rgba(196, 119, 67, 0.24);
}

.button-secondary {
  background: var(--color-primary);
  color: var(--color-white);
  border-color: var(--color-primary);
}

.button-secondary:hover {
  background: var(--color-primary-dark);
  border-color: var(--color-primary-dark);
}

.button-outline {
  background: transparent;
  color: var(--color-primary);
  border-color: var(--color-primary);
}

.button-outline:hover {
  background: var(--color-primary);
  color: var(--color-white);
}

.button-light {
  background: var(--color-white);
  color: var(--color-primary);
  border-color: var(--color-white);
}

.button-light:hover {
  background: var(--color-paper);
  border-color: var(--color-paper);
}

.button-small {
  min-height: 43px;
  padding: 0.65rem 1.1rem;
  font-size: 0.76rem;
}

.button-large {
  min-height: 60px;
  padding-inline: 2rem;
  font-size: 0.9rem;
}


/* 5. MOBILE NAVIGATION CONTROLS */

.mobile-menu-toggle {
  display: none;
  width: 46px;
  height: 46px;
  padding: 0;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  gap: 6px;
  background: transparent;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-sm);
  color: var(--color-primary);
  cursor: pointer;
}

.mobile-menu-toggle span {
  display: block;
  width: 20px;
  height: 2px;
  background: currentColor;
  transition:
    transform var(--transition-fast),
    opacity var(--transition-fast);
}

.mobile-menu-toggle[aria-expanded="true"] span:first-child {
  transform: translateY(8px) rotate(45deg);
}

.mobile-menu-toggle[aria-expanded="true"] span:nth-child(2) {
  opacity: 0;
}

.mobile-menu-toggle[aria-expanded="true"] span:last-child {
  transform: translateY(-8px) rotate(-45deg);
}


/* 6. HERO SECTION */

.hero {
  position: relative;
  display: flex;
  min-height: min(760px, calc(100svh - var(--header-height)));
  align-items: center;
  overflow: hidden;
  background: var(--color-primary-dark);
  color: var(--color-white);
}

.hero-background {
  position: absolute;
  z-index: 0;
  inset: 0;
  overflow: hidden;
}

.hero-background img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center 48%;
}

.hero-background::after {
  position: absolute;
  inset: 0;
  background:
    linear-gradient(
      90deg,
      rgba(20, 37, 47, 0.94) 0%,
      rgba(20, 37, 47, 0.83) 42%,
      rgba(20, 37, 47, 0.38) 75%,
      rgba(20, 37, 47, 0.12) 100%
    ),
    linear-gradient(
      0deg,
      rgba(20, 37, 47, 0.4),
      transparent 50%
    );
  content: "";
}

.hero-inner {
  position: relative;
  z-index: 1;
  width: min(
    var(--container-width),
    calc(100% - 48px)
  );
  padding-block: clamp(5rem, 10vw, 9rem);
  margin-inline: auto;
}

.hero-content {
  max-width: 790px;
}

.hero .eyebrow {
  color: var(--color-accent-light);
  margin-bottom: 1.5rem;
}

.hero h1 {
  max-width: 850px;
  margin-bottom: 1.5rem;
  color: var(--color-white);
  font-size: var(--font-size-hero);
  letter-spacing: -0.055em;
  line-height: 1.04;
}

.hero h1 span {
  color: var(--color-accent-light);
}

.hero-description {
  max-width: 620px;
  margin-bottom: 2rem;
  color: rgba(255, 255, 255, 0.86);
  font-size: clamp(1rem, 1.6vw, 1.2rem);
  line-height: 1.75;
}

.hero-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 1rem;
  margin-bottom: 2.5rem;
}

.hero-actions .button {
  min-width: 175px;
}

.hero-contact-note {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.8rem 1.5rem;
  color: rgba(255, 255, 255, 0.85);
  font-size: var(--font-size-sm);
}

.hero-contact-note a {
  color: var(--color-white);
  font-weight: var(--weight-bold);
  text-decoration: underline;
  text-decoration-color: var(--color-accent-light);
  text-underline-offset: 4px;
}

.hero-contact-note a:hover {
  color: var(--color-accent-light);
}


/* 7. HERO TRUST STRIP */

.hero-trust {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 1.25rem 2rem;
  margin-top: 2.75rem;
  padding-top: 1.5rem;
  border-top: 1px solid rgba(255, 255, 255, 0.25);
}

.hero-trust-item {
  display: flex;
  align-items: center;
  gap: 0.65rem;
  color: rgba(255, 255, 255, 0.9);
  font-size: 0.76rem;
  font-weight: var(--weight-semibold);
  letter-spacing: 0.035em;
}

.hero-trust-item strong {
  color: var(--color-white);
}

.trust-marker {
  display: inline-flex;
  width: 9px;
  height: 9px;
  flex: 0 0 9px;
  background: var(--color-accent);
  border-radius: 50%;
}


/* 8. OPTIONAL HERO IMAGE CAPTION */

.hero-caption {
  position: absolute;
  z-index: 2;
  right: 3%;
  bottom: 1.5rem;
  max-width: 240px;
  color: rgba(255, 255, 255, 0.75);
  font-size: 0.7rem;
  line-height: 1.5;
  text-align: right;
}


/* 9. SECONDARY CONVERSION BANNER */

.conversion-strip {
  position: relative;
  z-index: 2;
  background: var(--color-accent);
  color: var(--color-white);
}

.conversion-strip-inner {
  display: flex;
  width: min(
    var(--container-width),
    calc(100% - 48px)
  );
  min-height: 88px;
  margin-inline: auto;
  align-items: center;
  justify-content: space-between;
  gap: 1.5rem;
}

.conversion-strip p {
  margin: 0;
  font-family: var(--font-heading);
  font-size: 1rem;
  font-weight: var(--weight-semibold);
  line-height: 1.5;
}

.conversion-strip .button {
  flex: 0 0 auto;
  background: var(--color-white);
  color: var(--color-primary);
  border-color: var(--color-white);
}

.conversion-strip .button:hover {
  background: var(--color-paper);
}


/* 10. RESPONSIVE HEADER AND HERO */

@media (max-width: 1120px) {
  .header-inner {
    gap: 1rem;
  }

  .primary-navigation {
    gap: 0.8rem;
  }

  .primary-navigation ul {
    gap: 0.8rem;
  }

  .primary-navigation a {
    font-size: 0.75rem;
  }

  .brand-logo {
    max-width: 155px;
  }

  .header-phone {
    display: none;
  }
}

@media (max-width: 900px) {
  .header-inner {
    position: relative;
  }

  .mobile-menu-toggle {
    display: flex;
    flex: 0 0 auto;
